use crate::scene::*;
#[derive(Clone,Debug,PartialEq)]pub struct Mark{pub at:V,pub normal:V,pub radius:f32,pub opacity:f32,pub hardness:f32,pub color:[u8;3],pub erase:bool}
pub fn color(marks:&[Mark],p:V,normal:V,base:[u8;3])->[u8;3]{let mut c=base.map(|x|x as f32);for m in marks{if dot(normal,m.normal)<0.8{continue;}let delta=sub(p,m.at);if dot(delta,m.normal).abs()>m.radius*0.2+0.002{continue;}let distance=dot(delta,delta).sqrt()/m.radius;if distance>1.0{continue;}let weight=if distance<=m.hardness{1.0}else{(1.0-distance)/(1.0-m.hardness).max(0.001)}*m.opacity;let target=if m.erase{base}else{m.color};for k in 0..3{c[k]+=weight*(target[k]as f32-c[k]);}}c.map(|x|x.clamp(0.0,255.0)as u8)}
pub fn encode(marks:&[Mark])->String{if marks.is_empty(){return "-".into();}marks.iter().map(|m|format!("{},{},{},{},{},{},{},{},{},{},{},{},{}",m.at[0],m.at[1],m.at[2],m.normal[0],m.normal[1],m.normal[2],m.radius,m.opacity,m.hardness,m.color[0],m.color[1],m.color[2],m.erase as u8)).collect::<Vec<_>>().join(";")}
pub fn decode(s:&str)->Result<Vec<Mark>,String>{if s=="-"{return Ok(vec![]);}let mut marks=vec![];for item in s.split(';'){let v:Vec<f32>=item.split(',').map(|x|x.parse().map_err(|_|"Invalid paint number")).collect::<Result<_,_>>()?;if v.len()!=13||v.iter().any(|x|!x.is_finite())||!(0.002..=10.0).contains(&v[6])||!(0.0..=1.0).contains(&v[7])||!(0.0..=1.0).contains(&v[8])||v[9..12].iter().any(|x|!(0.0..=255.0).contains(x))||!matches!(v[12],0.0|1.0){return Err("Invalid paint stroke".into());}marks.push(Mark{at:[v[0],v[1],v[2]],normal:unit([v[3],v[4],v[5]]),radius:v[6],opacity:v[7],hardness:v[8],color:[v[9]as u8,v[10]as u8,v[11]as u8],erase:v[12]==1.0});if marks.len()>4096{return Err("Too many paint marks".into());}}Ok(marks)}
